import Assert from '#core/Assert.js';
import VarInt32 from '#data/VarInt32.js';

/**
 * A class for reading data at the bit level from {@link Uint8Array}.
 */
class BitBuffer {
    /**
     * @constructor
     * @param {Uint8Array} buffer
     */
    constructor(buffer) {
        this._buffer = buffer;

        this._pByte = 0;
        this._pBit = 0;
        this._totalBits = buffer.length * BITS_PER_BYTE;
    }

    /**
     * @static
     * @returns {number}
     */
    static get BITS_PER_BYTE() {
        return BITS_PER_BYTE;
    }

    /**
     * Reads an unsigned 32-bit integer from the given buffer, supporting buffers of length 1 to 4 bytes.
     *
     * @public
     * @static
     * @param {Uint8Array} buffer - The buffer to read from. Must be between 1 and 4 bytes long.
     * @returns {number} - The unsigned integer read from the buffer.
     * @throws {Error} If the buffer size is not between 1 and 4 bytes.
     */
    static readUInt32LE(buffer) {
        switch (buffer.byteLength) {
            case 1:
                return buffer[0] >>> 0;
            case 2:
                return (buffer[0] | (buffer[1] << 8)) >>> 0;
            case 3:
                return (buffer[0] | (buffer[1] << 8) | (buffer[2] << 16)) >>> 0;
            case 4:
                return (buffer[0] | (buffer[1] << 8) | (buffer[2] << 16) | (buffer[3] << 24)) >>> 0;
            default:
                throw new Error(`Unexpected buffer size [ ${buffer.byteLength} ]`);
        }
    }

    /**
     * Returns the number of read bits.
     *
     * @public
     * @returns {number}
     */
    getReadCount() {
        return this._pByte * BITS_PER_BYTE + this._pBit;
    }

    /**
     * Returns the number of remaining bits available to read in the buffer.
     *
     * @public
     * @returns {number}
     */
    getUnreadCount() {
        return this._totalBits - (this._pByte * BITS_PER_BYTE + this._pBit);
    }

    /**
     * Moves the internal read pointer forward or backward by a given number of bits.
     *
     * @public
     * @param {number} bits - Number of bits to move.
     */
    move(bits) {
        const abs = Math.abs(bits);

        if (abs === 0) {
            return;
        }

        if (bits > 0 && bits > this.getUnreadCount()) {
            throw new Error(`Cannot move pointer forward by ${bits} bits: only [ ${this.getUnreadCount()} ] bits unread`);
        }

        if (bits < 0 && abs > this.getReadCount()) {
            throw new Error(`Cannot move pointer backward by ${abs} bits: only [ ${this.getReadCount()} ] bits read`);
        }

        const numberOfBytes = Math.floor(abs / BITS_PER_BYTE);
        const numberOfBits = abs % BITS_PER_BYTE;

        if (bits > 0) {
            this._pByte += numberOfBytes;

            if (this._pBit + numberOfBits < BITS_PER_BYTE) {
                this._pBit += numberOfBits;
            } else {
                this._pByte += 1;
                this._pBit = (this._pBit + numberOfBits) % BITS_PER_BYTE;
            }
        }

        if (bits < 0) {
            this._pByte -= numberOfBytes;

            if (this._pBit - numberOfBits >= 0) {
                this._pBit -= numberOfBits;
            } else {
                this._pByte -= 1;
                this._pBit = BITS_PER_BYTE - Math.abs(this._pBit - numberOfBits);
            }
        }
    }

    /**
     * Fast backward pointer move without validation.
     * Used in hot paths where the count is known to be safe.
     *
     * @public
     * @param {number} count - Non-negative number of bits to move back.
     */
    moveBack(count) {
        if (count < 0) {
            return;
        }

        const total = this._pByte * BITS_PER_BYTE + this._pBit - count;

        this._pByte = total >>> 3;
        this._pBit = total & 7;
    }

    /**
     * Reads the specified number of bits.
     *
     * @public
     * @param {number} numberOfBits - The number of bits to read.
     * @param {boolean} [allocateNew=false] - Whether to allocate a new memory for returning buffer.
     * If `true`, a new buffer is allocated.
     * If `false` (default), a reusable buffer may be returned, which can be overwritten in subsequent operations.
     * @returns {Uint8Array}
     */
    read(numberOfBits, allocateNew = false) {
        const numberOfBytes = Math.ceil(numberOfBits / BITS_PER_BYTE);

        if (!allocateNew && numberOfBytes <= REUSABLE_BUFFER_SIZE) {
            return this._read(numberOfBits, pool[numberOfBytes - 1]);
        } else {
            return this._read(numberOfBits, new Uint8Array(numberOfBytes));
        }
    }

    /**
     * Reads n bits (up to 31) directly as an unsigned integer.
     *
     * @public
     * @param {number} n - Number of bits to read (1-31).
     * @returns {number}
     */
    readBitsAsUInt(n) {
        const totalBits = this._pBit + n;

        let raw;

        if (totalBits <= 8) {
            raw = this._buffer[this._pByte];
        } else if (totalBits <= 16) {
            raw = this._buffer[this._pByte] | (this._buffer[this._pByte + 1] << 8);
        } else if (totalBits <= 24) {
            raw = this._buffer[this._pByte] | (this._buffer[this._pByte + 1] << 8) | (this._buffer[this._pByte + 2] << 16);
        } else if (totalBits <= 32) {
            raw = (this._buffer[this._pByte] | (this._buffer[this._pByte + 1] << 8) | (this._buffer[this._pByte + 2] << 16) | (this._buffer[this._pByte + 3] << 24)) >>> 0;
        } else {
            const lo = (this._buffer[this._pByte] | (this._buffer[this._pByte + 1] << 8) | (this._buffer[this._pByte + 2] << 16) | (this._buffer[this._pByte + 3] << 24)) >>> 0;
            const hi = this._buffer[this._pByte + 4];
            const pBit = this._pBit;

            this._pByte += totalBits >>> 3;
            this._pBit = totalBits & 7;

            return (((lo >>> pBit) | (hi << (32 - pBit))) & ((1 << n) - 1)) >>> 0;
        }

        const pBit = this._pBit;

        this._pByte += totalBits >>> 3;
        this._pBit = totalBits & 7;

        return ((raw >>> pBit) & ((1 << n) - 1)) >>> 0;
    }

    /**
     * Reads the specified number of bits and writes them into the provided buffer.
     *
     * @public
     * @param {number} numberOfBits - The number of bits to read.
     * @param {Uint8Array} buffer - The buffer to write the results into.
     * @returns {Uint8Array}
     */
    readInBuffer(numberOfBits, buffer) {
        return this._read(numberOfBits, buffer);
    }

    /**
     * Reads an angle encoded in `n` bits from the buffer.
     *
     * @param {number} n - The number of bits.
     * @returns {number} - The angle.
     */
    readAngle(n) {
        return (this.readBitsAsUInt(n) * 360) / (1 << n);
    }

    /**
     * Reads a single bit from the buffer.
     *
     * @public
     * @returns {boolean}
     */
    readBit() {
        const value = ((this._buffer[this._pByte] >> this._pBit) & 1) === 1;

        if (this._pBit < 7) {
            this._pBit++;
        } else {
            this._pByte++;
            this._pBit = 0;
        }

        return value;
    }

    /**
     * Reads bytes from the buffer. Requires a byte alignment. Returns a view.
     *
     * @public
     * @param {number} count
     * @returns {Uint8Array}
     */
    readBytes(count) {
        Assert.isTrue(this._pBit === 0, 'readBytes requires byte alignment');

        if (this._pByte + count > this._buffer.length) {
            throw new Error(`Cannot read [ ${count} ] byte(s) - only [ ${this._buffer.length - this._pByte} ] byte(s) left`);
        }

        const start = this._pByte;

        this._pByte += count;

        return this._buffer.subarray(start, this._pByte);
    }

    /**
     * Reads a coordinate.
     *
     * @public
     * @returns {number}
     */
    readCoordinate() {
        let value = 0;

        const hasInteger = this.readBit();
        const hasFractional = this.readBit();

        if (hasInteger || hasFractional) {
            const sign = this.readBit();

            let integer = 0;

            if (hasInteger) {
                integer = this.readBitsAsUInt(14) + 1;
            }

            let fractional = 0;

            if (hasFractional) {
                fractional = this.readBitsAsUInt(5);
            }

            value = integer + fractional * (1 / (1 << 5));

            if (sign) {
                value = -value;
            }
        }

        return value;
    }

    /**
     * Reads a precise coordinate encoded in 20 bits.
     *
     * @public
     * @returns {number}
     */
    readCoordinatePrecise() {
        return this.readBitsAsUInt(20) * (360 / (1 << 20)) - 180;
    }

    /**
     * Reads 32 bits from the buffer and interprets them as a little-endian float.
     *
     * @public
     * @returns {number}
     */
    readFloat32() {
        const u32 = this.readUInt32();

        dataView.setUint32(0, u32, true);

        return dataView.getFloat32(0, true);
    }

    /**
     * Reads a normal value (normalized float in the range [-1.0, 1.0]) from the buffer.
     * The value is encoded using 12 bits, where the first bit indicates the sign
     * and the remaining 11 bits represent the magnitude.
     *
     * @public
     * @returns {number} The normalized value in the range [-1.0, 1.0].
     */
    readNormal() {
        const sign = this.readBit();
        const length = this.readBitsAsUInt(11);

        const value = length * (1 / ((1 << 11) - 1));

        if (sign) {
            return -value;
        } else {
            return value;
        }
    }

    /**
     * Reads a normal vector from the buffer.
     *
     * @public
     * @returns {Float32Array} An array containing the X, Y, and Z components of the normal vector.
     */
    readNormalVector() {
        const vector = new Float32Array(3);

        const hasX = this.readBit();
        const hasY = this.readBit();

        if (hasX) {
            vector[0] = this.readNormal();
        }

        if (hasY) {
            vector[1] = this.readNormal();
        }

        const negativeZ = this.readBit();

        const sum = Math.pow(vector[0], 2) + Math.pow(vector[1], 2);

        if (sum < 1) {
            vector[2] = Math.sqrt(1 - sum);
        } else {
            vector[2] = 0;
        }

        if (negativeZ) {
            vector[2] = -vector[2];
        }

        return vector;
    }

    /**
     * Reads a null-terminated string from the buffer, byte by byte,
     * until a zero byte is found or the optional length limit is reached.
     *
     * @public
     * @param {number=} length - Maximum number of bytes to read.
     * @returns {string} The decoded string.
     */
    readString(length) {
        const bytes = [ ];

        while (true) {
            if (Number.isInteger(length) && bytes.length >= length) {
                break;
            }

            const byte = this.readBitsAsUInt(BITS_PER_BYTE);

            if (byte === 0) {
                break;
            }

            bytes.push(byte);
        }

        return textDecoder.decode(new Uint8Array(bytes));
    }

    /**
     * Reads an unsigned 8-bit integer (1 byte) from the buffer.
     *
     * @public
     * @returns {number} The read unsigned integer (0–255).
     */
    readUInt8() {
        if (this._pBit === 0) {
            return this._buffer[this._pByte++] >>> 0;
        }

        return this.readBitsAsUInt(BITS_PER_BYTE);
    }

    /**
     * Reads exactly 32 bits as an unsigned integer (little-endian).
     *
     * @public
     * @returns {number}
     */
    readUInt32() {
        const buf = this._buffer;
        const pBit = this._pBit;
        const pByte = this._pByte;

        if (pBit === 0) {
            this._pByte = pByte + 4;

            return (buf[pByte] | (buf[pByte + 1] << 8) | (buf[pByte + 2] << 16) | (buf[pByte + 3] << 24)) >>> 0;
        }

        const lo = (buf[pByte] | (buf[pByte + 1] << 8) | (buf[pByte + 2] << 16) | (buf[pByte + 3] << 24)) >>> 0;
        const hi = buf[pByte + 4];

        this._pByte = pByte + 4;

        return (((lo >>> pBit) | (hi << (32 - pBit))) >>> 0);
    }

    /**
     * Reads exactly 64 bits as an unsigned BigInt (little-endian).
     *
     * @public
     * @returns {BigInt}
     */
    readUInt64() {
        const lo = this.readUInt32();
        const hi = this.readUInt32();

        dataView.setUint32(0, lo, true);
        dataView.setUint32(4, hi, true);

        return dataView.getBigUint64(0, true);
    }

    /**
     * Reads an unsigned variable-length integer encoded in Source 2's custom bit-packed format.
     * The initial 6 bits determine how many additional bits to read.
     *
     * @public
     * @returns {number} The decoded unsigned integer.
     */
    readUVarInt() {
        let result = this.readBitsAsUInt(6);

        switch (result & 48) {
            case 16: {
                result = (result & 15) | (this.readBitsAsUInt(4) << 4);

                break;
            }
            case 32: {
                result = (result & 15) | (this.readBitsAsUInt(8) << 4);

                break;
            }
            case 48: {
                result = (result & 15) | (this.readBitsAsUInt(28) << 4);

                break;
            }
            default: {
                break;
            }
        }

        return result >>> 0;
    }

    /**
     * Reads a signed variable-length integer from the buffer.
     *
     * @public
     * @returns {number} The decoded signed integer.
     */
    readVarInt32() {
        const unsigned = this.readUVarInt32();

        return (unsigned >> 1) ^ -(unsigned & 1);
    }

    /**
     * Reads a signed variable-length 64-bit integer from the buffer.
     *
     * @public
     * @returns {BigInt}
     */
    readVarInt64() {
        const unsigned = this.readUVarInt64();

        return (unsigned >> 1n) ^ -(unsigned & 1n);
    }

    /**
     * Reads an unsigned variable-length integer from the buffer.
     * Each byte contributes 7 bits to the result; the highest bit indicates continuation.
     *
     * @public
     * @returns {number} The decoded unsigned integer.
     */
    readUVarInt32() {
        let result = 0;
        let offset = 0;

        let byte;

        for (let i = 0; i < VarInt32.MAXIMUM_SIZE_BYTES; i++) {
            byte = this.readUInt8();

            result |= (byte & 0x7F) << (offset * 7);

            if ((byte & 0x80) === 0) {
                return result >>> 0;
            }

            offset += 1;
        }
    }

    /**
     * Reads an unsigned variable-length 64-bit integer from the buffer.
     * Each byte contributes 7 bits to the result; the highest bit indicates continuation.
     *
     * The maximum amount of bytes read possible here is 10. Here is why:
     *      1) 64-bit integer itself takes 8 bytes;
     *      2) Each byte includes a continuation bit (the highest bit). Therefore,
     *         a 9th byte is required. Since the 9th byte also has a continuation bit,
     *         it adds up to 9 bytes + 1 continuation bit, resulting in a total of 10 bytes
     *         to represent the maximum possible 64-bit integer.
     *
     * @public
     * @returns {BigInt}
     */
    readUVarInt64() {
        let continuation = true;
        let iterations = 0n;
        let value = 0n;

        while (continuation) {
            const byte = BigInt(this.readUInt8());

            if (iterations > 9n || (iterations === 9n && byte > 1n)) {
                throw new Error('Overflow');
            }

            value |= (byte & 127n) << (7n * iterations);

            continuation = (byte & 128n) === 128n;

            iterations++;
        }

        return value;
    }

    /**
     * Reads a variable-length unsigned integer representing a part of the {@link FieldPath}.
     * The number of bits read depends on a series of flags (prefix bits).
     *
     * @public
     * @returns {number}
     */
    readUVarIntFieldPath() {
        if (this.readBit()) {
            return this.readBitsAsUInt(2);
        }

        if (this.readBit()) {
            return this.readBitsAsUInt(4);
        }

        if (this.readBit()) {
            return this.readBitsAsUInt(10);
        }

        if (this.readBit()) {
            return this.readBitsAsUInt(17);
        }

        return this.readBitsAsUInt(31);
    }

    /**
     * Resets internal byte and bit pointers to the beginning of the buffer.
     *
     * @public
     */
    reset() {
        this._pByte = 0;
        this._pBit = 0;
    }

    /**
     * Reads the specified number of bits and writes them into the provided buffer.
     *
     * @protected
     * @param {number} numberOfBits - The number of bits to read.
     * @param {Uint8Array} buffer - The buffer to write the results into.
     * @returns {Uint8Array} - A buffer containing the read data.
     */
    _read(numberOfBits, buffer) {
        const unread = this.getUnreadCount();

        if (numberOfBits > unread) {
            throw new Error(`Unable to read [ ${numberOfBits} ] bit(s) - only [ ${unread} ] bit(s) left`);
        }

        const numberOfRequestedBytes = Math.ceil(numberOfBits / BITS_PER_BYTE);

        if (this._pBit === 0 && numberOfBits % BITS_PER_BYTE === 0) {
            buffer.set(this._buffer.subarray(this._pByte, this._pByte + numberOfRequestedBytes));

            this._pByte += numberOfRequestedBytes;

            return buffer;
        }

        if (numberOfBits % BITS_PER_BYTE === 0) {
            const mask = MASK_LEFT[BITS_PER_BYTE - this._pBit];

            for (let i = 0; i < numberOfRequestedBytes; i++) {
                const current = this._buffer[this._pByte + i];
                const next = this._buffer[this._pByte + i + 1];

                buffer[i] = (current >>> this._pBit) | ((next & mask) << (BITS_PER_BYTE - this._pBit));
            }

            this._pByte += numberOfRequestedBytes;

            return buffer;
        }

        const numberOfAffectedBytes = Math.ceil((this._pBit + numberOfBits) / BITS_PER_BYTE);

        let extraByte;

        if (numberOfAffectedBytes > numberOfRequestedBytes) {
            extraByte = this._buffer[this._pByte + numberOfAffectedBytes - 1];
        } else {
            extraByte = 0;
        }

        for (let i = 0; i < numberOfRequestedBytes; i++) {
            buffer[i] = this._buffer[this._pByte + i];
        }

        const zeroBitsIgnored = numberOfAffectedBytes * BITS_PER_BYTE - (this._pBit + numberOfBits);

        buffer[0] &= MASK_RIGHT[this._pBit];

        if (numberOfAffectedBytes > numberOfRequestedBytes) {
            extraByte &= MASK_LEFT[zeroBitsIgnored];
        } else {
            buffer[buffer.length - 1] &= MASK_LEFT[zeroBitsIgnored];
        }

        if (this._pBit > 0) {
            buffer[0] = buffer[0] >>> this._pBit;

            for (let i = 0; i < numberOfRequestedBytes; i++) {
                let next;

                if (i < numberOfRequestedBytes - 1) {
                    next = buffer[i + 1];
                } else {
                    next = extraByte;
                }

                buffer[i] |= (next & MASK_LEFT[BITS_PER_BYTE - this._pBit]) << (BITS_PER_BYTE - this._pBit);

                if (i < numberOfRequestedBytes) {
                    buffer[i + 1] = buffer[i + 1] >>> this._pBit;
                }
            }
        }

        const totalBits = this._pBit + numberOfBits;

        this._pByte += totalBits >>> 3;
        this._pBit = totalBits & 7;

        return buffer;
    }
}

const BITS_PER_BYTE = 8;

const MASK_LEFT = [ 255, 127, 63, 31, 15, 7, 3, 1 ];
const MASK_RIGHT = [ 255, 254, 252, 248, 240, 224, 192, 128 ];

const REUSABLE_BUFFER_SIZE = 8;

const reusable = new Uint8Array(REUSABLE_BUFFER_SIZE);

const pool = [ ];

for (let i = 0; i < REUSABLE_BUFFER_SIZE; i++) {
    pool.push(reusable.subarray(0, i + 1));
}

const dataViewBuffer = new ArrayBuffer(8);
const dataView = new DataView(dataViewBuffer);

const textDecoder = new TextDecoder();

export default BitBuffer;
